UPDATE public.mad_clubs SET profile = $p${"slogan": "경상권 최초 광고 연합 동아리", "universities": "대구·경북 지역 (경북대학교 중심)", "intro": "ADlle은 대구, 경북대학생 중심의 경상권 최초 광고 연합 동아리입니다. '광고'라는 공통 관심사 하나로 다양한 지역·학교·학과의 대학생이 모여, 지역 개발에 보탬이 되는 광고인을 꿈꾸며 실무진의 지도 아래 체계적인 광고·마케팅 커리큘럼으로 활동합니다.", "stats": [{"label": "누적 부원", "value": "약 130명 (2024.5)"}, {"label": "4기 부원", "value": "25명"}, {"label": "부서", "value": "3개 (기획·카피·디자인)"}], "teams": [{"name": "기획부", "desc": "브리프 속 과제와 타깃에 따라 상황을 분석하고 문제를 도출한 뒤 솔루션을 고안합니다. 플로우와 로직을 짜 탄탄하고 체계적인 제안서·기획서를 작성합니다.", "fit": "#광고·마케팅에 관심 있는 #논리적인 #원활하고 유연한 커뮤니케이션"}, {"name": "카피부", "desc": "더 설득력 있는 기획서를 위해 기획부와 함께 플로우와 로직을 짜고, 이에 걸맞은 콘셉트 도출과 네이밍을 맡습니다.", "fit": "#설득력 있는 #한 줄의 중요성을 아는 #세상을 다르게 보는 시각"}, {"name": "디자인부", "desc": "플로우와 로직을 도식화하고 IMC 솔루션 목업을 디자인하며 기획서 전반의 디자인과 틀을 다듬습니다. 보다 실전적·실무적인 광고 디자인 업무를 담당합니다.", "fit": "#디자인 능력자가 되고 싶은 #트렌드에 민감한 #피드백을 수용할 줄 아는"}], "programs": [{"title": "부서 스터디", "desc": "한 달에 두 번 비대면으로 진행합니다. 소속 부서와 상관없이 원하는 수업을 골라 들으며 멀티 플레이어로 성장합니다."}, {"title": "해커톤", "desc": "약 17시간 동안 팀별로 랜덤 세부 주제와 타깃을 뽑아 PDF 25매 이내 기획서를 완성하는 활동. 1기 공익광고 캠페인, 2기 ESG IMC, 3기 사계절 라면, 4기 편의점 콜라보를 주제로 진행했습니다."}, {"title": "경쟁 PT 프로젝트", "desc": "레드오션 시장에서 경쟁사 대비 제품 충성도를 이끌 카피와 방안을 찾아 세일즈를 극대화할 프로모션을 기획하고 경쟁 PT로 발표합니다."}, {"title": "역 브리프 프로젝트", "desc": "실제 집행된 광고를 보고 기획 의도와 광고 목표를 추론해 브리프를 작성하고 IMC 전략을 고안합니다."}, {"title": "광고기업 탐방 · 실무진 특강", "desc": "광고 기업을 직접 방문하고 현업 실무진의 이야기를 가까이서 듣는 프로그램입니다."}, {"title": "기업 연계 프로젝트", "desc": "다양한 지역·학교·학과의 동아리원이 모두 참여하는 기업 연계 공모 프로젝트입니다."}, {"title": "인스타그램 콘텐츠", "desc": "자신의 관심 분야를 파악해 자유로운 양식의 콘텐츠로 직접 제작하며 광고해 보는 활동입니다."}], "projects": [{"year": "2023", "client": "스파크랜드", "title": "스파크랜드 활성화 방안 공모전", "type": "기업 연계", "result": "6개 타깃·컨셉 도출 후 경쟁 PT, 우수팀 실무 미팅"}, {"year": "2024", "client": "LG유플러스", "title": "멤버십 마케팅 프로젝트 (매드리그)", "type": "기업 연계", "result": "본사 경쟁 PT 후 아이디어 구체화·실현"}, {"year": "2024", "client": "지평주조", "title": "지평막걸리 시장 확장 프로젝트 (매드리그)", "type": "기업 연계", "result": "내부 예선 후 최종 경쟁 PT 진출"}, {"year": "2022~2024