contest": "오더그레이 산학협력 온라인 마케팅 전략 부문", "prize": "최우수상"}, {"year": "2020", "contest": "대한민국 대학생 광고대회 KOSAC", "prize": "입선"}, {"year": "2020", "contest": "대경강원권 지역문화 콘텐츠 개발 페스티벌", "prize": "수상"}, {"year": "2020", "contest": "경상북도 독립운동기념관장상", "prize": "수상"}, {"year": "2020", "contest": "글로벌 스타트업 디자인씽킹 해커톤", "prize": "은상"}, {"year": "2020", "contest": "제주 창업 아이디어 해커톤", "prize": "장려상"}, {"year": "2020", "contest": "대구·경북권 대학 연합 창업 캠프", "prize": "혁신상"}, {"year": "2020", "contest": "ruck 아이디어 경진 대회", "prize": "2등"}], "network": [{"name": "한화그룹", "kind": "특강"}, {"name": "대홍기획", "kind": "특강"}, {"name": "HSAD", "kind": "특강"}, {"name": "이노션", "kind": "특강"}, {"name": "디마이너스원", "kind": "특강"}]}$p$::jsonb, description = COALESCE(NULLIF(description,''), '대구·경북 대학생이 모인 경상권 최초 광고 연합 동아리. 실무진 교육과 기업 연계 프로젝트로 미래 광고인을 키웁니다.'), profile_updated_at = now() WHERE slug = 'adlle' AND profile = '{}'::jsonb;

UPDATE public.mad_clubs SET profile = $p${"full_name": "부산지역대학생연합광고연구회 (PUSAN AD MANIA)", "intro": "PAM은 부산 지역 대학생이 모인 광고 연합 동아리입니다. 기획·영상·디자인 3개 팀 체제로 전문성을 키우고, 매년 기업·기관과 협업하는 경쟁 PT와 캠페인, 사이드 프로젝트로 실전 경험을 쌓습니다.", "stats": [{"label": "팀 구성", "value": "3개 (기획·영상·디자인)"}, {"label": "연간 경쟁 PT", "value": "매년 3개 기업"}, {"label": "소속 팀 선택", "value": "6개월마다 가능"}], "teams": [{"name": "기획팀", "desc": "기획의 시작인 브리프 분석을 배우고 역 브리프 실습으로 기획 방향을 설정합니다. 매주 경쟁 PT를 진행하며 기획서 작성의 기초부터 실전까지 익힙니다."}, {"name": "영상팀", "desc": "카메라 특강을 듣고 촬영을 실습합니다. 직접 광고를 제작하고 피드백을 받으며 카메라 활용과 영상 제작 방법을 배웁니다."}, {"name": "디자인팀", "desc": "디자인 장비를 적정 가격에 구매하는 방법부터 작업물의 요소를 해체하는 실습까지, 실무에 필요한 과정을 중심으로 배웁니다."}], "programs": [{"title": "웰컴 프로젝트", "desc": "전년도 공모전 과제로 진행하는 신입생과의 첫 경쟁 PT입니다."}, {"title": "팀 스터디", "desc": "3개 팀으로 나뉘어 이론 학습과 실습을 진행합니다."}, {"title": "기업 경쟁 PT", "desc": "매년 3개 기업과 협업하는 경쟁 PT 공모전을 진행합니다."}, {"title": "광고제", "desc": "매년 말 PAM의 광고제를 엽니다."}, {"title": "팜이즘", "desc": "1년간의 활동 내역을 잡지 형식으로 엮어 제작합니다."}, {"title": "사이드 프로젝트", "desc": "프로젝트 참여를 희망하는 부원들과 함께 진행합니다."}], "projects": [{"client": "전자랜드", "title": "브랜드 필름", "type": "기업 경쟁 PT"}, {"client": "부스트 X 스트롱 애드", "title": "부스트 영상 광고 (60초·90초)", "type": "기업 경쟁 PT"}, {"year": "2016~2019", "client": "부산경찰", "title": "공익 캠페인 (착한 오지랖·가까워 톡·노(老)관심·실종 및 학대 방지)", "type": "기업 경쟁 PT"}, {"year": "2024", "client": "부산광역시 한의사회", "title": "한의학 홍보 공모전 (2012년 협약 후 14회째)", "type": "기업 경쟁 PT"}, {"client": "대선주조", "title": "시원블루 30초 광고 시리즈", "type": "기업 경쟁 PT"}, {"client": "지평주조", "title": "지평막걸리 시장 확장", "type": "기업 경쟁 PT"}, {"client": "자갈치시장", "title": "자갈치시장 상권 활성화 제안", "type": "기업 경쟁 PT"}, {"year": "2024", "client": "KCQA (Korea Coffee Quality Association)", "title": "2024 CBT TEAM SPIRIT BREWING TOURNAMENT 정체성 디자인·홍보 전략", "type": "사이드 프로젝트"}, {"client": "삼진어묵", "title": "비킹후스 캠퍼스어택", "type": "사이드 프로젝트"}, {"client": "삼진어묵", "title": "프로틴 바 캠퍼스어택", "type": "사이드 프로젝트"}, {"client": "LG U+", "title": "유플투쁠 경쟁 PT 및 TF 실행", "type": "사이드 프로젝트"}, {"client": "오토 셀렉션", "