 "contest": "KOSAC 부산 예선", "prize": "은상"}, {"year": "2010~2014", "contest": "제32회 제일기획 광고대상", "prize": "파이널리스트"}, {"year": "2010~2014", "contest": "제30회 대홍기획 크리에이티브 어워즈 기획서 부문", "prize": "대상"}, {"year": "2010~2014", "contest": "제29회 대홍기획 크리에이티브 어워즈", "prize": "금상"}, {"year": "2010~2014", "contest": "ALL 잘 풀리는 집 전국 경쟁 PT", "prize": "최우수상"}, {"year": "2010~2014", "contest": "BIC 아이디어 공모전", "prize": "동상"}, {"year": "2010~2014", "contest": "팔도 공모전 기획서 부문", "prize": "장려상"}, {"year": "2010~2014", "contest": "KT&G 상상실현 창의력 공모전 인쇄 부문", "prize": "장려상"}, {"year": "2010~2014", "contest": "비통 99초 패러디 영화제", "prize": "우수상"}, {"year": "2010~2014", "contest": "제13회 부산광역시 디지털 영상콘텐츠 공모전", "prize": "장려상"}, {"year": "2010~2014", "contest": "제4회 유니브 엑스포", "prize": "최우수 동아리"}, {"year": "2010~2014", "contest": "CM SONG/ACTIVITY 부문", "prize": "수상"}, {"year": "2010~2014", "contest": "제4회 비락광고 공모전", "prize": "수상"}]}$p$::jsonb, description = COALESCE(NULLIF(description,''), '부산 지역 대학생 연합 광고 연구회. 기획·영상·디자인 3개 팀이 기업·기관과 경쟁 PT와 캠페인을 실전으로 수행합니다.'), profile_updated_at = now() WHERE slug = 'pam' AND profile = '{}'::jsonb;

UPDATE public.mad_clubs SET profile = $p${"full_name": "제주 대학생 광고 연합 수작 (Jeju AD Lab Union SUZAK)", "slogan": "Think + Design × Action", "intro": "서로 말을 주고받는 '수작'에서 빼어난 작품을 뜻하는 수작(秀作)으로의 성장을 의미하는, 제주 대학생 광고·마케팅 연합입니다. 단순한 스터디 그룹이 아니라 실전 경험과 전국 네트워크를 통해 지역의 문제를 함께 고민하고 해결하는 프로젝트 형식으로 운영하며, 마케팅·광고·디자인·영상 기획 등 다양한 분야의 협업으로 아이디어를 구체화하고 실현합니다.", "values": [{"title": "Think", "desc": "깊이 있는 고민으로 인사이트를 도출합니다."}, {"title": "Design", "desc": "창의적 기획으로 문제를 해결합니다."}, {"title": "Action", "desc": "실전 프로젝트 실행을 목표로 합니다."}], "teams": [{"name": "기획팀", "desc": "기획서·아이디어 보드 제작, 시장 분석과 인사이트 도출, 기업 제안서 작성 및 피드백"}, {"name": "디자인팀", "desc": "브랜드 아이덴티티 기획, 마케팅·광고 크리에이티브 디자인, 인쇄물·디지털 콘텐츠 제작"}, {"name": "영상팀", "desc": "영상 기획·스토리보드 작성, 브랜드·공익 캠페인 영상 제작, Visual Storytelling 기반 마케팅 콘텐츠 제작"}], "programs": [{"title": "실전 프로젝트 중심 활동", "desc": "로컬 기업·스타트업·공공기관 등과 협업해 실제 마케팅·광고 프로젝트를 수행합니다."}, {"title": "로컬 가치 증진", "desc": "제주 지역 브랜드와 협업해 공익 캠페인을 기획하고 실행하는 기회를 제공합니다."}, {"title": "현업 전문가 멘토링", "desc": "대행사·제작사 등 업계 실무자와 연계해 실질적인 강연과 피드백을 제공합니다."}, {"title": "전국 네트워크 형성", "desc": "수도권·전국 단위의 매드리그와 협력하며 공모전, 아이디어 무브먼트, 경쟁 PT 등을 경험합니다."}, {"title": "자기 개발 및 진로 탐색", "desc": "네트워킹으로 다양한 사람들과 교류하며 개인의 성장과 진로 방향을 설정합니다."}], "schedule": [{"when": "2월", "title": "회원 모집 및 선발", "desc": "멘토링 구성"}, {"when": "3월", "title": "오리엔테이션(OT)", "desc": "기본 소양 교육, 팀 구성"}, {"when": "상반기", "title": "팀별 스터디", "desc": "제안서 작성 실습, 로컬 브랜드 조사"}, {"when": "상반기", "title": "기업 제안 실무", "desc": "기업 PT 발표 및 피드백"}, {"when": "상반기", "title": "실무자 특강", "desc": "로컬 브랜드 강연"}, {"when": "7월", "title": "상반기 네트워킹", "desc": "현업 실무자 및 회원 간 교류"}, {"when": "하반기", "title": "팀별 스터디 활동 · 기수 결산", "desc": "차기 집행부 구성, 로컬 마케팅 기획"}, {"when": "하반기", "title": "로컬 마케팅 경쟁 PT", "desc": "기업과 협업 프로젝트"}, {"when": "12월", "title": "하반기 네트워킹", "desc": "기업-학생 네트워킹 행사"}, {"when": "연말", "title": "활동 보고서 및 매거진 발행"}]}$p$::jsonb, description = COALESCE(NULLIF(description,''), '제주 지역 대학생의 창의적 역량 강화를 목표로 운영하는 광고·마케팅 연합. 실전 프로젝트와 전국 네트워크로 성장합니다.'), profile_updated_at = now() WHERE slug = 'suzak' AND profile = '{}'::jsonb;

UPDATE public.mad_clubs SET profile = $p${"intro": "2022~2024년 활동을 기준으로, 영상·디자인·광고 공모전 수상과 SBA 프로젝트, 다수 브랜드와의 협업으로 실전 경험을 쌓아 온 동아리입니다.", "projects": [{"year": "2022~2024", "client": "SBA", "title": "DDP 상설전시장 활성화 프로젝트", "type": "기업 연계"}, {"year": "2022~2024", "client": "SBA", "title": "뷰티패션브랜드 영상광고 콘테스트", "type": "공모전"}], "awards": [{"year": "2022", "contest": "해양경찰청 해양오염예방 콘텐츠 공모전", "prize": "푸른바다상"}, {"year": "2022", "contest": "대한민국 정부광고 크리에이티브", "prize": "최우수상"}, {"year": "2022", "contest": "이노션 SOS 광고제", "prize": "동상"}, {"year": "2022", "contest": "제2회 외국어 남용에 불편했던 이야기 영상 공모전", "prize": "북돋음상"}, {"year": "2022", "contest": "서울영상공모전", "prize": "입선"}, {"year": "2023", "contest": "학교폭력예방 스마트폰 영상제", "prize": "우수상"}, {"year": "2023", "contest": "아웃캠퍼스 선정 명품동아리 TOP50", "prize": "선정"}], "network": [{"name": "에스팀", "kind": "협업"}, {"name": "벨킨코리아", "kind": "협업"}, {"name": "Shift-3", "kind": "협업"}, {"name": "지평막걸리", "kind": "협업"}]}$p$::jsonb, description = COALESCE(NULLIF(description,''), '영상·광고 공모전과 기업 협업으로 실전 경험을 쌓는 MADLeague 동아리 (2022~2024 활동 기준).'), profile_updated_at = now() WHERE slug = 'madleap' AND profile = '{}'::jsonb;
